#!/usr/bin/env python3
"""Apply a Quickshell palette to the desktop's installed appearance configs."""
import json
import fcntl
import tempfile
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys

HOME = Path.home()
CONFIG = Path(os.environ.get("XDG_CONFIG_HOME", HOME / ".config"))
from appearance_targets import apply_fastfetch, load_jsonc, nearest_native_accent
from hypr_appearance import apply_hypr_appearance
from notification_theme import apply_notification_theme

# Serialize writes even across shell reloads; generated files use atomic replacement.
lock_root = Path(os.environ.get("XDG_RUNTIME_DIR", tempfile.gettempdir()))
lock_file = (lock_root / ("quickshell-appearance-" + str(os.getuid()) + ".lock")).open("a")
fcntl.flock(lock_file, fcntl.LOCK_EX)

if len(sys.argv) != 3:
    raise SystemExit("usage: apply-theme.py THEME_ID PALETTE_JSON")

theme_id = sys.argv[1]
p = json.loads(sys.argv[2])
p.setdefault("accent", p["aqua"])
p.setdefault("accentDark", p["blueDark"])
p.setdefault("accentSoft", p["surfaceAlt"])
p.setdefault("onAccent", p["bg0"])
p.setdefault("onAccentContainer", p["text"])
p.setdefault("onError", p["bg0"])
required = {
    "bgDim", "bg0", "surface", "surfaceAlt", "surfaceRaised", "border",
    "mutedStrong", "muted", "text", "textBright", "red", "green", "blue",
    "yellow", "purple", "orange", "aqua", "gray0", "gray1", "gray2",
}
if not required.issubset(p):
    raise SystemExit("palette is missing required color roles")


def write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".tmp")
    temp.write_text(content, encoding="utf-8")
    temp.replace(path)


def colors_css() -> str:
    roles = {
        "bg0": p["bg0"], "bg1": p["surface"], "bg2": p["surfaceAlt"],
        "bg3": p["surfaceRaised"], "bg4": p["border"], "fg": p["text"],
        "red": p["red"], "orange": p["orange"], "yellow": p["yellow"],
        "green": p["green"], "aqua": p["accent"], "accent": p["accent"], "onAccent": p["onAccent"], "blue": p["blue"],
        "purple": p["purple"], "grey0": p["muted"], "grey1": p["gray1"],
        "grey2": p["gray0"],
    }
    return "/* Generated by Quickshell theme switcher. */\n" + "".join(
        f"@define-color {name} {value};\n" for name, value in roles.items()
    )


# Generate complete native themes and notify running GTK applications.
from desktop_theme import apply_gtk_palette
from icon_palette import build_colloid_overlay
icon_name = None
try:
    icon_name = build_colloid_overlay(p)
except (OSError, ValueError, subprocess.SubprocessError) as error:
    print("Folder icon palette update failed:", error, file=sys.stderr)
try:
    apply_gtk_palette(p, theme_id, CONFIG, icon_name=icon_name)
except (OSError, subprocess.SubprocessError) as error:
    print("GTK appearance update failed:", error, file=sys.stderr)

# Fastfetch uses the primary accent itself, rather than a fixed ANSI-blue slot.
try:
    apply_fastfetch(p, CONFIG, write)
except (OSError, ValueError, TypeError) as error:
    print("Fastfetch appearance update failed:", error, file=sys.stderr)

# Shared GTK-style color definitions used by Waybar.
write(CONFIG / "waybar/colors/gruvbox-material.css", colors_css())

# SwayNC consumes the same semantic roles as the notch and Settings.
apply_notification_theme(p, CONFIG, write)
write(CONFIG / "swaync/colors/gruvbox-material.css", colors_css())

# Update the active Rofi palette and its custom theme from their saved templates.
rofi_colors = f'''/* Generated by Quickshell theme switcher. */
* {{
    background: {p['bg0']}FF;
    background-alt: {p['surface']}FF;
    foreground: {p['text']}FF;
    selected: {p['accent']}FF;
    active: {p['green']}FF;
    urgent: {p['red']}FF;
}}
'''
write(CONFIG / "rofi/colors/gruvbox-material.rasi", rofi_colors)
rofi_template = CONFIG / "rofi/type-1/style-7.template.rasi"
if rofi_template.exists():
    rasi = rofi_template.read_text(encoding="utf-8")
    for old, new in {
        "#282828": p["surface"], "#32302f": p["surfaceAlt"],
        "#3c3836": p["surfaceRaised"], "#504945": p["border"],
        "#a89984": p["muted"], "#d4be98": p["text"], "#ddc7a1": p["textBright"],
        "#ea6962": p["red"], "#a9b665": p["green"], "#7daea3": p["blue"],
        "#d8a657": p["yellow"], "#d3869b": p["purple"], "#e78a4e": p["orange"],
    }.items():
        rasi = re.sub(re.escape(old), new, rasi, flags=re.IGNORECASE)
    write(CONFIG / "rofi/type-1/style-7.rasi", rasi)

# Kitty reads this included file when it starts or reloads its configuration.
kitty = f'''# Generated by Quickshell theme switcher.\nforeground {p['text']}\nbackground {p['bg0']}\nselection_foreground {p['bg0']}\nselection_background {p['surfaceRaised']}\ncursor {p['accent']}\ncursor_text_color {p['onAccent']}\nurl_color {p['accent']}\nactive_border_color {p['accent']}\ninactive_border_color {p['border']}\nbell_border_color {p['yellow']}\nactive_tab_foreground {p['onAccent']}\nactive_tab_background {p['accent']}\ninactive_tab_foreground {p['muted']}\ninactive_tab_background {p['surface']}\ntab_bar_background {p['bg0']}\ncolor0 {p['bg0']}\ncolor1 {p['red']}\ncolor2 {p['green']}\ncolor3 {p['yellow']}\ncolor4 {p['blue']}\ncolor5 {p['purple']}\ncolor6 {p['aqua']}\ncolor7 {p['text']}\ncolor8 {p['mutedStrong']}\ncolor9 {p['redBright']}\ncolor10 {p['green']}\ncolor11 {p['yellow']}\ncolor12 {p['blue']}\ncolor13 {p['purple']}\ncolor14 {p['aqua']}\ncolor15 {p['textBright']}\n'''
write(CONFIG / "kitty/colors/colors.conf", kitty)
# Refresh already-open Kitty windows so a profile switch is visible immediately.
if shutil.which("pkill"):
    subprocess.run(["pkill", "-USR1", "-x", "kitty"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)

# Keep the Starship prompt segments in sync with the active desktop palette.
starship_template = CONFIG / "quickshell/templates/starship.toml.template"
if starship_template.exists():
    starship = starship_template.read_text(encoding="utf-8")
    starship = starship.replace("{{onAccent}}", p["onAccent"])
    for role in ("bg0", "blue", "aqua", "gray0", "surfaceRaised", "text", "red"):
        starship = starship.replace("{{" + role + "}}", p["accent"] if role == "aqua" else p[role])
    write(CONFIG / "starship.toml", starship)

# Keep the installed Equicord/Vesktop theme, but feed it the current palette.
discord_template = CONFIG / "quickshell/templates/Equicord-Gruvbox.css"
if discord_template.exists():
    discord = discord_template.read_text(encoding="utf-8")
    discord_roles = {
        "gruv-dark-bg-hard": "bg0", "gruv-dark-bg": "surface",
        "gruv-dark-bg-alt": "bg0", "gruv-dark-bg-soft": "surfaceAlt",
        "gruv-dark-bg1": "surfaceRaised", "gruv-dark-bg2": "border",
        "gruv-dark-bg3": "mutedStrong", "gruv-dark-bg4": "gray0",
        "gruv-dark-fg-hard": "textBright", "gruv-dark-fg": "textLight",
        "gruv-dark-fg1": "textBright", "gruv-dark-fg2": "text",
        "gruv-dark-fg3": "muted", "gruv-dark-purple-dark": "purpleDark",
        "gruv-dark-purple-light": "purple", "gruv-dark-yellow-dark": "yellowDark",
        "gruv-dark-yellow-light": "yellow", "gruv-dark-red-dark": "redDark",
        "gruv-dark-red-light": "red", "gruv-dark-orange-dark": "orange",
        "gruv-dark-orange-light": "orange", "gruv-dark-blue-dark": "blueDark",
        "gruv-dark-blue-light": "blue", "gruv-dark-green-dark": "greenDark",
        "gruv-dark-green-light": "green", "gruv-dark-aqua-dark": "greenDark",
        "gruv-dark-aqua-light": "aqua", "gruv-dark-gray-dark": "gray1",
        "gruv-dark-gray-light": "muted",
    }
    for variable, role in discord_roles.items():
        rgb = ", ".join(str(int(p[role][i:i + 2], 16)) for i in (1, 3, 5))
        discord = re.sub(
            rf"({re.escape('--' + variable)}:\s*)([0-9]+(?:\s*,\s*|\s+)[0-9]+(?:\s*,\s*|\s+)[0-9]+)",
            lambda match: match.group(1) + (rgb if "," in match.group(2) else rgb.replace(",", "")), discord,
        )
    for variable, role in (("gruv-dark-accent", "accent"), ("gruv-dark-accent-hover", "accentDark"), ("gruv-dark-button-text-default", "onAccent"), ("gruv-dark-link-color", "accent")):
        rgb = ", ".join(str(int(p[role][i:i + 2], 16)) for i in (1, 3, 5))
        discord = re.sub(rf"(--{variable}:\s*)[^;]+;", lambda match: match.group(1) + rgb + ";", discord)
    discord = discord.replace("@name Gruvbox Dark", "@name Desktop Theme")
    discord = discord.replace("Gruvbox Dark for Discord", "Palette from the desktop theme switcher")
    write(CONFIG / "Equicord/themes/Gruvbox.css", discord)

# VSCodium's UI follows the same palette while preserving the user's other settings.
codium = CONFIG / "VSCodium/User/settings.json"
if codium.exists():
    try:
        settings = load_jsonc(codium)
        ui = {
            "editor.background": p["bg0"], "editor.foreground": p["text"],
            "editorCursor.foreground": p["accent"], "editorLineNumber.foreground": p["muted"],
            "editorLineNumber.activeForeground": p["textBright"],
            "editorGutter.background": p["bg0"], "editorOverviewRuler.border": p["border"],
            "editor.selectionBackground": p["surfaceRaised"], "editor.lineHighlightBackground": p["surface"],
            "editor.selectionHighlightBackground": p["accentSoft"], "editor.findMatchBackground": p["yellowDark"],
            "editorBracketHighlight.foreground1": p["aqua"],
            "editorBracketHighlight.foreground2": p["yellow"],
            "editorBracketHighlight.foreground3": p["purple"],
            "editorBracketHighlight.foreground4": p["blue"],
            "editorBracketHighlight.foreground5": p["green"],
            "editorBracketHighlight.foreground6": p["orange"],
            "sideBar.background": p["bg0"], "sideBar.foreground": p["text"], "sideBar.border": p["border"],
            "activityBar.background": p["surface"], "activityBar.foreground": p["text"],
            "activityBar.activeBorder": p["accent"], "activityBarBadge.background": p["accent"],
            "activityBarBadge.foreground": p["onAccent"], "titleBar.activeBackground": p["surface"],
            "titleBar.activeForeground": p["text"], "tab.activeBackground": p["bg0"],
            "tab.inactiveBackground": p["surface"], "tab.activeForeground": p["text"],
            "tab.activeBorderTop": p["accent"], "tab.unfocusedActiveBorderTop": p["border"],
            "panel.background": p["bg0"], "panel.border": p["border"],
            "panelTitle.activeBorder": p["accent"],
            "statusBar.background": p["accent"], "statusBar.foreground": p["onAccent"],
            "input.background": p["surfaceAlt"], "input.foreground": p["text"],
            "inputOption.activeBorder": p["accent"],
            "button.background": p["accent"], "button.foreground": p["onAccent"], "button.hoverBackground": p["accent"],
            "list.activeSelectionBackground": p["surfaceRaised"],
            "list.activeSelectionForeground": p["textBright"], "list.focusOutline": p["accent"],
            "list.hoverBackground": p["surfaceAlt"], "focusBorder": p["accent"],
            "terminal.background": p["bg0"], "terminal.foreground": p["text"],
            "terminalCursor.foreground": p["accent"],
            "terminal.ansiBlack": p["bg0"], "terminal.ansiRed": p["red"],
            "terminal.ansiGreen": p["green"], "terminal.ansiYellow": p["yellow"],
            "terminal.ansiBlue": p["blue"], "terminal.ansiMagenta": p["purple"],
            "terminal.ansiCyan": p["aqua"], "terminal.ansiWhite": p["text"],
            "terminal.ansiBrightBlack": p["mutedStrong"], "terminal.ansiBrightRed": p["redBright"],
            "terminal.ansiBrightGreen": p["green"], "terminal.ansiBrightYellow": p["yellow"],
            "terminal.ansiBrightBlue": p["blue"], "terminal.ansiBrightMagenta": p["purple"],
            "terminal.ansiBrightCyan": p["aqua"], "terminal.ansiBrightWhite": p["textBright"],
        }
        ui.update({
            "foreground": p["text"], "descriptionForeground": p["muted"], "disabledForeground": p["mutedStrong"],
            "errorForeground": p["red"], "selection.background": p["surfaceRaised"],
            "widget.border": p["border"], "widget.shadow": p["bgDim"] + "99",
            "dropdown.background": p["surfaceAlt"], "dropdown.foreground": p["text"], "dropdown.border": p["border"],
            "menu.background": p["surfaceAlt"], "menu.foreground": p["text"], "menu.border": p["border"],
            "menu.selectionBackground": p["surfaceRaised"], "menu.selectionForeground": p["textBright"],
            "menu.selectionBorder": p["accent"], "menu.separatorBackground": p["border"],
            "quickInput.background": p["surface"], "quickInput.foreground": p["text"],
            "quickInputTitle.background": p["surfaceAlt"],
            "editorWidget.background": p["surface"], "editorWidget.foreground": p["text"], "editorWidget.border": p["border"],
            "editorHoverWidget.background": p["surface"], "editorHoverWidget.foreground": p["text"],
            "editorHoverWidget.border": p["border"], "editorHoverWidget.statusBarBackground": p["surfaceAlt"],
            "editorSuggestWidget.background": p["surface"], "editorSuggestWidget.foreground": p["text"],
            "editorSuggestWidget.border": p["border"], "editorSuggestWidget.highlightForeground": p["accent"],
            "editorSuggestWidget.selectedBackground": p["surfaceRaised"],
            "notifications.background": p["surface"], "notifications.foreground": p["text"], "notifications.border": p["border"],
            "notificationCenterHeader.background": p["surfaceAlt"], "notificationCenterHeader.foreground": p["text"],
            "notificationsErrorIcon.foreground": p["red"], "notificationsWarningIcon.foreground": p["yellow"],
            "notificationsInfoIcon.foreground": p["blue"],
            "input.border": p["border"], "input.placeholderForeground": p["muted"],
            "inputValidation.errorBackground": p["redDark"], "inputValidation.errorBorder": p["red"],
            "inputValidation.warningBackground": p["yellowDark"], "inputValidation.warningBorder": p["yellow"],
            "inputValidation.infoBackground": p["blueDark"], "inputValidation.infoBorder": p["blue"],
            "button.secondaryBackground": p["surfaceRaised"], "button.secondaryForeground": p["text"],
            "button.secondaryHoverBackground": p["border"], "button.border": p["border"],
            "list.inactiveSelectionBackground": p["surfaceAlt"], "list.inactiveSelectionForeground": p["text"],
            "list.highlightForeground": p["accent"], "list.errorForeground": p["red"], "list.warningForeground": p["yellow"],
            "badge.background": p["accent"], "badge.foreground": p["onAccent"], "progressBar.background": p["accent"],
            "textLink.foreground": p["accent"], "textLink.activeForeground": p["accent"],
            "titleBar.inactiveBackground": p["bg0"], "titleBar.inactiveForeground": p["muted"], "titleBar.border": p["border"],
            "statusBar.noFolderBackground": p["surface"], "statusBar.noFolderForeground": p["text"],
            "statusBar.debuggingBackground": p["orange"], "statusBar.debuggingForeground": p["bg0"],
            "statusBarItem.remoteBackground": p["accent"], "statusBarItem.remoteForeground": p["onAccent"],
            "statusBarItem.errorBackground": p["red"], "statusBarItem.errorForeground": p["bg0"],
            "statusBarItem.warningBackground": p["yellow"], "statusBarItem.warningForeground": p["bg0"],
            "gitDecoration.addedResourceForeground": p["green"], "gitDecoration.modifiedResourceForeground": p["yellow"],
            "gitDecoration.deletedResourceForeground": p["red"], "gitDecoration.untrackedResourceForeground": p["accent"],
            "gitDecoration.ignoredResourceForeground": p["mutedStrong"], "gitDecoration.conflictingResourceForeground": p["orange"],
            "editorError.foreground": p["red"], "editorWarning.foreground": p["yellow"], "editorInfo.foreground": p["blue"],
            "editorHint.foreground": p["accent"],
        })
        custom = settings.get("workbench.colorCustomizations", {})
        custom.update(ui)
        settings["workbench.colorCustomizations"] = custom
        if "gruvbox" in settings.get("workbench.colorTheme", "").lower():
            settings["workbench.colorTheme"] = "Default Dark Modern"
        syntax = {
            "textMateRules": [
                {"scope": ["comment", "punctuation.definition.comment"], "settings": {"foreground": p["muted"], "fontStyle": "italic"}},
                {"scope": ["string", "string.quoted", "constant.other.symbol"], "settings": {"foreground": p["green"]}},
                {"scope": ["constant.numeric", "constant.language", "constant.character"], "settings": {"foreground": p["yellow"]}},
                {"scope": ["keyword", "storage", "storage.type", "keyword.control"], "settings": {"foreground": p["purple"]}},
                {"scope": ["entity.name.function", "support.function", "meta.function-call"], "settings": {"foreground": p["aqua"]}},
                {"scope": ["entity.name.type", "entity.name.class", "support.type", "support.class"], "settings": {"foreground": p["blue"]}},
                {"scope": ["variable", "variable.parameter", "meta.definition.variable"], "settings": {"foreground": p["text"]}},
                {"scope": ["entity.name.tag", "entity.other.attribute-name"], "settings": {"foreground": p["red"]}},
                {"scope": ["invalid", "invalid.illegal"], "settings": {"foreground": p["textBright"], "background": p["redDark"]}},
                {"scope": ["markup.heading", "entity.name.section"], "settings": {"foreground": p["aqua"], "fontStyle": "bold"}},
            ],
            "semanticTokenColors": {
                "comment": p["muted"], "string": p["green"], "number": p["yellow"],
                "keyword": p["purple"], "function": p["aqua"], "method": p["aqua"],
                "class": p["blue"], "interface": p["blue"], "type": p["blue"],
                "enum": p["yellow"], "namespace": p["purple"], "parameter": p["orange"],
                "variable": p["text"], "property": p["blue"], "operator": p["textBright"],
                "decorator": p["orange"],
            },
        }
        semantic_rules = syntax.pop("semanticTokenColors")
        semantic = settings.get("editor.semanticTokenColorCustomizations", {})
        semantic["enabled"] = True
        semantic.setdefault("rules", {}).update(semantic_rules)
        settings["editor.semanticTokenColorCustomizations"] = semantic
        token_custom = settings.get("editor.tokenColorCustomizations", {})
        token_custom.pop("semanticTokenColors", None)
        token_custom.update(syntax)
        settings["editor.tokenColorCustomizations"] = token_custom
        write(codium, json.dumps(settings, ensure_ascii=False, indent=4) + "\n")
    except (ValueError, OSError) as error:
        print("VSCodium appearance update failed:", error, file=sys.stderr)

# Native ChatGPT/Codex desktop appearance is separate from GTK.
chatgpt_sync = CONFIG / "quickshell/sync-chatgpt-theme.py"
if chatgpt_sync.exists():
    subprocess.run([sys.executable, str(chatgpt_sync), json.dumps(p)], check=False)

# Apply the accent and Hyprland border colors to the current session.
accent = nearest_native_accent(p["accent"])
if shutil.which("gsettings"):
    subprocess.run(["gsettings", "set", "org.gnome.desktop.interface", "accent-color", accent], check=False)
apply_hypr_appearance(p, CONFIG, write)

# Refresh running style daemons when they are present.
def running(name: str) -> bool:
    return bool(shutil.which("pgrep") and subprocess.run(["pgrep", "-x", name], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode == 0)

if running("swaync") and shutil.which("swaync-client"):
    subprocess.run(["swaync-client", "--reload-css"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
if running("waybar") and shutil.which("pkill"):
    subprocess.run(["pkill", "-USR2", "-x", "waybar"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False)
